#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

int getMaxDigit(const string& s) {
    int result = 0;
    for (char c : s)
        result = max(result, c - '0');
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    while (cin >> s >> t) {
        int base = max(2, max(getMaxDigit(s), getMaxDigit(t)) + 1);

        if (s.size() > t.size())
            swap(s, t);

        s = string(t.size() - s.size(), '0') + s;

        int carry = 0;
        for (int i = static_cast<int>(t.size()) - 1; i >= 0; --i)
            carry = (carry + (s[i] - '0') + (t[i] - '0')) / base;

        cout << t.size() + (carry != 0) << '\n';
    }

    return 0;
}

